sys_script.script:
(function executeRule(current, previous /* null when async */) {

    /* =====================================================
       CAMPUSMATCH — CREATE COLLECTION DEADLINE
    ===================================================== */

    // Run ONLY when Claim becomes Approved
    if (!current.claim_status.changesTo('Approved')) {
        return;
    }

    // Safety checks
    if (!current.item || !current.claimant) {
        return;
    }

    var DEADLINE_TABLE =
        'x_snc_campusmatch_campusmatch_deadline';


    /* -----------------------------------------------------
       PREVENT DUPLICATE ACTIVE COLLECTION DEADLINES
    ----------------------------------------------------- */

    var existing =
        new GlideRecord(DEADLINE_TABLE);

    existing.addQuery(
        'claim',
        current.getUniqueValue()
    );

    existing.addQuery(
        'deadline_type',
        'collection'
    );

    existing.addQuery(
        'status',
        'active'
    );

    existing.setLimit(1);
    existing.query();

    if (existing.hasNext()) {
        return;
    }


    /* -----------------------------------------------------
       CALCULATE DEADLINE

       HACKATHON / DEMO:
       3 DAYS FROM APPROVAL
    ----------------------------------------------------- */

    var start =
        new GlideDateTime();

    var due =
        new GlideDateTime(start);

    due.addDaysUTC(3);


    /* -----------------------------------------------------
       CREATE DEADLINE
    ----------------------------------------------------- */

    var deadline =
        new GlideRecord(DEADLINE_TABLE);

    deadline.initialize();

    deadline.setValue(
        'deadline_type',
        'collection'
    );

    deadline.setValue(
        'item',
        current.getValue('item')
    );

    deadline.setValue(
        'claim',
        current.getUniqueValue()
    );

    deadline.setValue(
        'user',
        current.getValue('claimant')
    );

    deadline.setValue(
        'start_date_time',
        start
    );

    deadline.setValue(
        'due_date_time',
        due
    );

    deadline.setValue(
        'status',
        'active'
    );

    deadline.setValue(
        'reminder_sent',
        false
    );

    deadline.setValue(
        'expiry_processed',
        false
    );

    deadline.insert();

})(current, previous);
